function boundaryOfBinaryTree(root) {
  const result = [root.val];
  const isLeaf = (node) => node.left === null && node.right === null;
  const addLeaves = (node) => {
    if (node === null) {
      return;
    }
    if (isLeaf(node)) {
      result.push(node.val);
      return;
    }
    addLeaves(node.left);
    addLeaves(node.right);
  };
  let node = root.left;
  while (node !== null && !isLeaf(node)) {
    result.push(node.val);
    node = node.left !== null ? node.left : node.right;
  }
  addLeaves(root.left);
  addLeaves(root.right);
  const rightSide = [];
  node = root.right;
  while (node !== null && !isLeaf(node)) {
    rightSide.push(node.val);
    node = node.right !== null ? node.right : node.left;
  }
  for (let k = rightSide.length - 1; k >= 0; k--) {
    result.push(rightSide[k]);
  }
  return result;
}

