function boundaryOfBinaryTree(root) {
  // One pre-order pass that carries "still on the left edge" and "still on the right edge" flags:
  // left-edge nodes are written on the way down, leaves when met, right-edge nodes on the way back up.
  const out = [root.val];
  const walk = (node, onLeft, onRight) => {
    if (!node) return;
    const leaf = !node.left && !node.right;
    if (leaf) out.push(node.val);
    else if (onLeft) out.push(node.val);
    walk(node.left, onLeft, onRight && !node.right);
    walk(node.right, onLeft && !node.left, onRight);
    if (!leaf && onRight) out.push(node.val);
  };
  walk(root.left, true, false);
  walk(root.right, false, true);
  return out;
}

