function generate(rand, size) {
  const total = size === 'large' ? 700 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? 1000 : 9;
  const value = () => Math.floor(rand() * (2 * span + 1)) - span;
  // Small trees sometimes grow from the newest free slot, which makes long paths and zig-zags.
  const chainy = size === 'small' ? rand() * 0.9 : 0;
  const root = { val: value(), left: null, right: null };
  const free = [[root, 'left'], [root, 'right']];
  for (let count = 1; count < total; count++) {
    const index = rand() < chainy ? free.length - 1 - (rand() < 0.5 ? 1 : 0) : Math.floor(rand() * free.length);
    const [parent, side] = free.splice(index, 1)[0];
    const node = { val: value(), left: null, right: null };
    parent[side] = node;
    if (rand() < 0.5) free.push([node, 'left'], [node, 'right']);
    else free.push([node, 'right'], [node, 'left']);
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
